import pandas as pd
from common import *
def run():
 out=ROOT/'outputs/r77';out.mkdir(exist_ok=True);positions=ROOT/'outputs/r76/nominal_positions.parquet';coverage=ROOT/'outputs/r76/target_coverage.json';intervals=ROOT/'outputs/r17/intervals.csv';evpath=EP32/'extensions/v5_rdagent_onset_forecast/outputs/daily_input_audit.json';bench=CACHE/'forecast_v5/CSI_ALL.parquet'
 pos=pd.read_parquet(positions);cov={(x['method'],pd.Timestamp(x['origin'])):x for x in json.loads(coverage.read_text())};iv=pd.read_csv(intervals,parse_dates=['origin','entry','exit']);iv=iv[iv.origin.isin(pos.origin.unique())];calendar=pd.DatetimeIndex(pd.read_parquet(bench).index);ids=sorted(pos.security_id.unique());idx={s:i for i,s in enumerate(ids)};prices=np.full((len(calendar),len(ids)),np.nan);chains=np.full(prices.shape,-1,dtype=np.int32);volume=np.zeros(prices.shape,bool);buy=np.zeros(prices.shape,dtype=np.uint8);sell=buy.copy();ev=json.loads(evpath.read_text());paths={Path(p).stem:Path(p) for p in ev['reads'] if '/normalized/prices_qfq/' in p};hashes={}
 for j,sid in enumerate(ids):
  p=paths[sid];h=sha(p);assert h==ev['reads'][str(p)];hashes[str(p)]=h;f=pd.read_parquet(p,columns=['date','qfq_close','close_conflict','factor_chain_id','volume','volume_conflict','can_buy','can_sell']).set_index('date').reindex(calendar);price=pd.to_numeric(f.qfq_close);prices[:,j]=price.where(price.gt(0)&f.close_conflict.eq(False));chains[:,j]=pd.factorize(f.factor_chain_id)[0];volume[:,j]=(pd.to_numeric(f.volume).gt(0)&f.volume_conflict.eq(False)).to_numpy()
  for name,a in [('can_buy',buy),('can_sell',sell)]:a[:,j]=np.where(f[name].eq(True),1,np.where(f[name].eq(False),2,0))
  if (j+1)%1500==0:print('R77 read',j+1,len(ids),flush=True)
 groups={k:g for k,g in pos.groupby(['method','origin'])};rows=[];detail=[]
 for x in iv.itertuples():
  g=groups[(x.method,x.origin)];columns=[idx[s] for s in g.security_id];lo=calendar.get_loc(x.entry);hi=calendar.get_loc(x.exit);p=prices[lo:hi+1,columns];ch=chains[lo:hi+1,columns];valid=np.isfinite(p).all(axis=0);stable=(ch==ch[0]).all(axis=0)&(ch[0]>=0);good=valid&stable;w=g.weight.to_numpy();u=cov[(x.method,x.origin)]['unknown_weight'];ready=bool(u<1e-12 and good.all() and np.isclose(w.sum(),1));ret=float(w@(p[-1]/p[0])-1) if ready else None
  rows.append(dict(method=x.method,origin=x.origin,entry=x.entry,exit=x.exit,stocks=len(g),unknown_weight=u,price_bad=int((~valid).sum()),chain_bad=int((~stable).sum()),unvalued_known_weight=float(w[~good].sum()),full_path_valued=ready,fixed_stock_gross=ret,r17_status=x.status,r17_gross=float(x.gross_return) if pd.notna(x.gross_return) else None,gross_difference=ret-x.gross_return if ready and pd.notna(x.gross_return) else None,buy_unknown=int((buy[lo,columns]==0).sum()),sell_unknown=int((sell[hi,columns]==0).sum()),buy_disallowed=int((buy[lo,columns]==2).sum()),sell_disallowed=int((sell[hi,columns]==2).sum()),endpoint_volume_bad=int((~volume[lo,columns]|~volume[hi,columns]).sum())))
  for j,z in enumerate(g.itertuples()):detail.append(dict(method=x.method,origin=x.origin,security_id=z.security_id,weight=z.weight,price_valid=bool(valid[j]),chain_stable=bool(stable[j]),entry_price=p[0,j],exit_price=p[-1,j]))
 js(out/'intervals.json',rows);pd.DataFrame(detail).to_parquet(out/'stock_interval_audit.parquet',index=False);summary=[]
 for method in sorted(pos.method.unique()):
  q=[x for x in rows if x['method']==method];ok=[x for x in q if x['full_path_valued']];summary.append(dict(method=method,planned=len(q),valued=len(ok),unknown_identity_intervals=sum(x['unknown_weight']>=1e-12 for x in q),price_gap_intervals=sum(x['price_bad']>0 for x in q),chain_gap_intervals=sum(x['chain_bad']>0 for x in q),mean_difference_complete=float(np.mean([x['gross_difference'] for x in ok])) if ok else None,whole_path_valid=len(ok)==len(q)))
 js(out/'summary.json',summary);inputs=[positions,coverage,intervals,evpath,bench,ROOT/'protocols/r77.json',Path(__file__)];js(out/'receipt.json',dict(reads={str(p):sha(p) for p in inputs},price_partitions=hashes,intervals=len(rows),stock_rows=len(detail),no_net_curve=True));print(json.dumps(summary,ensure_ascii=False))
if __name__=='__main__':run()
